// Тикет #07650fd9 (07650fd9d421f9aaf1bdceb7) — עבר QA 13.10.2026, iPhone, TestFlight 1.0.0 (19).
// Факт 13.10 (скрины 07650fd9-ios-b19-journey-scroll-statusbar.png, 07650fd9-ios-b15-vs-b19-statusbar.png): на «המסע שלי» и «בית»
// при прокрутке контент не заходит под строку статуса — сверху полоса фона. Белый текст статус-бара на светлом фоне ПРИНЯТ пользователем как есть
// (не проверяем и не считаем ошибкой).
// Геометрия: прокручиваемая область начинается не выше нижнего края строки статуса (контент обрезается ею, а не уходит под часы),
// и после прокрутки ни один видимый текст не начинается выше строки статуса с заходом в неё.
// @manual-check: пиксельно — под часами/батареей нет кусков текста/карточек (сверить по скрину).
import { $$, driver, expect } from '@wdio/globals';
import { swipeUp } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { rectOf, statusBarHeight, switchTabAndCheck } from '../_lib/app-1310.ts';

/** Главная прокручиваемая область экрана (самая большая видимая ScrollView). */
async function mainScroll() {
  const list = driver.isAndroid
    ? await $$('android=new UiSelector().scrollable(true)')
    : await $$('-ios class chain:**/XCUIElementTypeScrollView');
  let best: WebdriverIO.Element | undefined, bestArea = 0;
  for (const el of list) {
    const r = await rectOf(el).catch(() => null);
    if (!r) continue;
    const a = r.width * r.height;
    if (a > bestArea) { bestArea = a; best = el; }
  }
  if (!best) throw new Error('Нет прокручиваемой области');
  return best;
}

async function checkNoContentUnderStatusBar(tab: string) {
  await toHome();
  await switchTabAndCheck(tab);
  const sb = await statusBarHeight();
  expect(sb).toBeGreaterThan(0);
  for (let i = 0; i < 3; i++) await swipeUp();
  await driver.pause(600);

  // 1. Прокручиваемая область начинается у нижнего края строки статуса или ниже.
  const sc = await rectOf(await mainScroll());
  expect(sc.y).toBeGreaterThanOrEqual(sb - 1);

  // 2. Тексты внутри области после прокрутки: ни один не виден частично в зоне строки статуса
  //    (рамка, пересекающая y=sb сверху, допустима только если обрезана областью прокрутки — её верх ≥ sb, проверено в п.1).
  const texts = driver.isAndroid
    ? await $$('android=new UiSelector().className("android.widget.TextView")')
    : await $$('-ios class chain:**/XCUIElementTypeScrollView/**/XCUIElementTypeStaticText');
  let crossing = 0;
  for (const t of texts) {
    const r = await rectOf(t).catch(() => null);
    if (!r || r.height <= 0) continue;
    if (r.y >= 0 && r.y < sb - 1 && r.y + r.height > 0) crossing++;
  }
  console.log(`[JR-07] «${tab}»: строка статуса ${sb}, верх прокрутки ${sc.y}, текстов, начинающихся в зоне статуса: ${crossing} (обрезаются областью прокрутки). @manual-check по скрину.`);
}

describe('Строка статуса при прокрутке', () => {
  afterEach(async () => { await toHome(); });

  it('JR-07 «המסע שלי» и «בית»: при прокрутке контент не заходит под строку статуса #07650fd9 @prod-safe @manual-check', async () => {
    await checkNoContentUnderStatusBar('המסע שלי');
    await checkNoContentUnderStatusBar('בית');
  });
});
